            "swapping_pxa_to_pxs_is_instant_the": "PXA से PXS में रूपांतरण तत्काल होता है: आधा PXA तुरंत रूपांतरित होता है, 5% शुल्क काटकर, जबकि बाकी आधा संपार्श्विक के रूप में बंद रहता है और ~3.5 दिनों के बाद उस समय की कीमत के अनुसार समायोजित होकर लौटता है। PXS से PXA में रूपांतरण पर कोई शुल्क नहीं लगता और यह ~3.5 दिनों के बाद उस समय की witnesses की माध्यिका कीमत पर निपटता है।",
            "pxp_usable_because": "{{text}} <0>{{overall}}</0> PXP उपयोग योग्य, क्योंकि <1>{{borrowed}}</1> उधार लिए गए और <2>{{lended}}</2> उधार दिए गए।",
            "strong_strong_can_transfer_pixa_power_directly": "<strong>@{{username}}</strong> मानक 13-सप्ताह के power down चक्र को दरकिनार करते हुए Pixa Power सीधे किसी अन्य खाते में भेज सकता है। यह कोषागार एक बहु-हस्ताक्षर खाता है, इसलिए कोई अकेला लॉगिन इसके धन को नहीं हिला सकता — नीचे <strong>थोक हस्तांतरण</strong> का उपयोग करें, जहाँ प्रत्येक की-धारक उसी बैच पर अलग से हस्ताक्षर करता है, फिर उसे मिलाकर प्रसारित किया जाता है।",
            "the_big_mac_index_is_a_renown": "Big Mac सूचकांक एक प्रसिद्ध आर्थिक सूचकांक है जो क्रयशक्ति, मुद्रास्फीति और उपभोक्ता मूल्य पर नज़र रखता है।",
            "beware_of_spam_and_phishing_links_in": "हस्तांतरण मेमो में स्पैम और फ़िशिंग लिंक से सावधान रहें। जिन उपयोगकर्ताओं पर भरोसा न हो उनके लिंक न खोलें। अपनी प्राइवेट कीज़ किसी तीसरे पक्ष की वेबसाइट को कभी न दें। लेनदेन तब तक नहीं दिखेंगे जब तक वे ब्लॉकचेन पर पुष्ट न हो जाएँ, जिसमें कुछ मिनट लग सकते हैं।",
            "are_you_sure_you_want_to_power": "क्या आप वाकई {{amount}} PXA का power up करना चाहते हैं? इससे तरल PXA स्टेक की गई Pixa Power में बदल जाता है।",
            "are_you_sure_you_want_to_power_2": "क्या आप वाकई {{amount}} PXP का power down करना चाहते हैं? इसका भुगतान 13 साप्ताहिक किश्तों में होगा।",
            "are_you_sure_you_want_to_swap": "क्या आप वाकई {{amount}} PXA को PXS में रूपांतरित करना चाहते हैं? आधा तुरंत रूपांतरित होता है, 5% शुल्क काटकर, और PXS तुरंत जमा हो जाता है। बाकी आधा संपार्श्विक के रूप में बंद रहता है और ~3.5 दिनों के बाद उस समय की PXA कीमत के अनुसार समायोजित होकर लौटता है; यदि कीमत आधी हो गई हो, तो कुछ भी नहीं लौटता। रूपांतरण वापस नहीं लिए जा सकते।",
            "are_you_sure_you_want_to_swap_2": "क्या आप वाकई {{amount}} PXS को PXA में रूपांतरित करना चाहते हैं? PXS अभी आपके शेष से निकल जाता है, और PXA ~3.5 दिनों के बाद उस समय की witnesses की माध्यिका कीमत पर पहुँचता है। कोई शुल्क नहीं है। रूपांतरण वापस नहीं लिए जा सकते।",
