            "not_taxable_disposals_or_income_proposal_fees": "ये कर योग्य निपटान या आय नहीं हैं। प्रस्ताव शुल्क खाते से जाते हैं और आपकी होल्डिंग घटाते हैं; पूर्ण हुई बचत निकासियाँ और power up आंतरिक गतिविधियाँ हैं, जो पूर्णता के लिए दिखाई गई हैं।",
            "seen_in_history_but_not_booked_into": "इतिहास में दिखे पर ऊपर के आँकड़ों में दर्ज नहीं ({{skippedTotal}} संक्रियाएँ) — शेष पर असर न डालने वाली सामाजिक/अभिशासन क्रियाएँ, दावे के समय पहले ही गिनी गई आय, या बाद में निष्पादन पर निपटने वाली गतिविधियाँ:",
            "reconstructed_from_classified_events": "{{ingest}} वर्गीकृत घटनाओं से पुनर्निर्मित।{{text}}{{fiat}}{{text_2}}{{note}}",
            "deductions_optional_losses_you_carried_forward_f": "कटौतियाँ — वैकल्पिक। पिछले वर्षों से अग्रेनीत हानियाँ इस वर्ष के लाभ को घटाती हैं; वार्षिक छूट का आँकड़ा बताता है कि आपके देश की छूट का कितना हिस्सा आप कहीं और उपयोग कर चुके हैं। जहाँ आपका क्षेत्राधिकार अनुमति देता है, यह स्वतः लागू होती है।",
            "send_labels_are_assigned_in_the_classify": "भेजने के लेबल वर्गीकरण चरण में दिए जाते हैं और प्रति खाता याद रखे जाते हैं। चाहें तो उन्हें स्प्रेडशीट में एक साथ संपादित करें:",
            "say_what_each_outbound_send_was_so": "बताएँ कि प्रत्येक जावक भुगतान क्या था, ताकि उस पर सही कर लगे। जब तक आप लेबल न दें, हर भेजा गया लेनदेन कर योग्य बिक्री माना जाता है — अपना एक्सचेंज, अपने वॉलेट, उपहार या दान के रूप में चिह्नित करने से कर बदल जाता है। लेबल अगली बार याद रहेंगे। जारी रखें उन्हें लागू कर रिपोर्ट पुनः गणना करता है।",
            "nothing_to_classify_no_outbound_transfers_to": "वर्गीकृत करने को कुछ नहीं — आपके इतिहास में तीसरे पक्ष को कोई जावक हस्तांतरण नहीं मिला। समीक्षा और निर्यात के लिए आगे बढ़ें।",
            "opening_balances_are_tokens_you_already_held": "प्रारंभिक शेष वे टोकन हैं जो इस खाते की पहली दर्ज संक्रिया से पहले ही आपके पास थे। इन्हें सेट करें ताकि पुराने निपटानों का वास्तविक लागत आधार हो, न कि शून्य-लागत वाला (बढ़ा-चढ़ाकर दिखाया) लाभ। लागत वह कुल राशि है जो आपने उस प्रारंभिक मात्रा के लिए {{cur}} में चुकाई।",
            "generate_a_record_of_your_on_chain": "एक तिथि सीमा में अपनी ऑन-चेन गतिविधि का अभिलेख बनाएँ, जिसे FairFlow इंजन कर के लिए वर्गीकृत करता है। विकल्प भरें, अपने भुगतान वर्गीकृत करें, फिर PDF, CSV या JSON में निर्यात करें।",
            "values_use_the_wallets_current_price_a": "मान वॉलेट के वर्तमान {{fiat}} मूल्य का उपयोग करते हैं — बिना ऐतिहासिक फ़ीड का एकल सजीव स्नैपशॉट, इसलिए होल्डिंग का कुल सटीक है पर वसूल किए गए लाभ अनुमानित हैं (निपटान की प्राप्ति और लागत आधार दोनों वही वर्तमान मूल्य साझा करते हैं)। सटीक लाभ के लिए ऐतिहासिक oracle / Kursliste स्रोत जोड़ें।",
            "fiat_values_come_from_the_engines_pxs": "फ़िएट मान इंजन के PXS-संदर्भित डेमो मूल्य प्रदाता ({{priceDataVersion}}) से आते हैं — आँकड़ों पर भरोसा करने से पहले वास्तविक oracle / Kursliste स्रोत जोड़ें।",
