            "below_the_floor_the_haircut_falls_linearly_toward": "तल के नीचे कटौती रैखिक रूप से शून्य की ओर गिरती है। निपटान पाठ से कड़ाई से कम सौंपता है — आत्मा सच्चाई से संकेत देती है कि शरीर थका है। यह ईमानदारी है, स्थिरीकरण नहीं।",
            "viable_corridor": "व्यवहार्य गलियारा",
