            "reserves_sit_at_three_to_ten_times": "भंडार उस भार के तीन से दस गुने पर रहते हैं जिसे मन नाम देता है। कटौती एक के बराबर होती है। निष्पादन के क्षण में पाठ पूरा-पूरा निभाया जाता है।",
