            "the_body_simply_has_more_capacity_than": "शरीर के पास आवश्यकता से अधिक क्षमता होती है; निपटान अपरिवर्तित चलता रहता है। गलियारा स्वयं भी सर्वसम्मति से बदला जा सकता है।",
