            "no_banking_risk": "कोई बैंकिंग जोखिम नहीं",
            "nothing_references_the_banking_system": "बैंकिंग प्रणाली का कोई संदर्भ नहीं",
            "1_the_weight": "1× भार",
            "3_floor": "3× तल",
            "10_capacity": "10× क्षमता",
            "delivered": "सौंपा गया",
            "held_back_by_haircut": "कटौती द्वारा रोका गया",
            "when_you_settle_the_body_is_delivered": "निपटान के समय शरीर निष्पादन के क्षण में PXA के रूप में सौंपा जाता है — वह राशि जो ओरैकल-निहित भार को कटौती से गुणा करने पर बनती है। इसीलिए «अंतर्निहित» शब्द ग़लत है: अंतर्निहित का अर्थ है दो अलग परिसंपत्तियाँ, एक वस्तु और उस पर बना व्युत्पन्न। किंतु supra और atlas दो वस्तुएँ नहीं हैं। वे एक ही शरीर हैं, दो स्तरों पर देखा हुआ — शरीर वही है जो वह है; supra वह है जो मन कहता है कि यह शरीर प्रक्षेपित करे। चेतना कोई ऐसी वस्तु नहीं जिसका शरीर स्वामी हो। वह जागा हुआ शरीर ही है।",
            "no_monetary_mechanism_removes_risk_a_stablecoin_concentrates": "कोई भी मौद्रिक तंत्र जोखिम को मिटाता नहीं। फ़िएट-भंडार सिक्का उसे उस भंडार की अखंडता और निर्गमकर्ता की शोधनक्षमता में केंद्रित कर देता है। supra उस जोखिम को रचनात्मक अर्थव्यवस्था की अस्थिरता — एटलस के प्रसरण — और सर्वसम्मति की अखंडता — witnesses के दिक्सूचक की दृढ़ता — पर स्थानांतरित करता है, और फिर उसे किसी बचाए गए अंक के पीछे छिपाने के बजाय अधि-संपार्श्विकीकरण तथा कुछ भी न बचाने वाली कटौती के द्वारा खुले में सँभालता है।",
            "body_at_the_weight": "{{label}} पर शरीर भार",
            "pixa_supra_pxs": "Pixa Supra · PXS",
