            "effective_in_strong_strong_day": "— <strong>%n</strong> {{{_plurals.day}}} में प्रभावी",
            "adding_a_password_provides_extra_security_especi": "पासवर्ड अतिरिक्त सुरक्षा देता है, विशेषकर छोटी सीड वाक्यांशों के लिए।",
            "you_are_about_to_request_a_change": "आप <0>@{{username}}</0> के लिए पुनर्प्राप्ति खाता बदलने का अनुरोध करने जा रहे हैं।",
            "nominate_a_trusted_account_a_co_founder": "एक विश्वसनीय खाता नामित करें — कोई सह-संस्थापक, आपका अपना दूसरा वॉलेट, या ऐसा संपर्क जिससे आप किसी और माध्यम से जुड़ सकें — जो आपकी owner की खो जाने या असुरक्षित हो जाने पर पहुँच वापस पाने में मदद करे। पुनर्प्राप्ति प्रक्रिया आपकी owner की के इतिहास का उपयोग करती है, इसलिए पुनर्प्राप्ति खाता अकेले कभी आपका खाता नहीं ले सकता: वह केवल उसे वापस पाने में सहायता कर सकता है। परिवर्तन 30 दिनों की प्रतीक्षा अवधि के बाद प्रभावी होते हैं।",
            "strong_30_day_waiting_period_strong_changing": "<strong>30 दिन की प्रतीक्षा अवधि।</strong> पुनर्प्राप्ति खाता बदलना तत्काल नहीं होता। नया अनुरोध <strong>प्रसारण के 30 दिन बाद</strong> प्रभावी होता है; तब तक वर्तमान पुनर्प्राप्ति खाता ही लागू रहता है। प्रतीक्षा अवधि में दोबारा प्रसारण लंबित अनुरोध को बदल देता है। वर्तमान मान फिर से सेट करने पर लंबित परिवर्तन रद्द हो जाता है।",
            "pick_someone_you_trust_personally_a_co": "ऐसा व्यक्ति चुनें जिस पर आप व्यक्तिगत रूप से भरोसा करते हों: कोई सह-संस्थापक, आपका अपना दूसरा खाता, या ऐसा वॉलेट जिसके स्वामी से आप किसी और माध्यम से संपर्क कर सकें।",
            "generate_a_fresh_seed_phrase_to_derive": "अपने खाते के लिए नई कीज़ प्राप्त करने हेतु नया सीड वाक्यांश बनाएँ। आपका सीड वाक्यांश आपके सभी खाता कीज़ की मास्टर की है — इसे सुरक्षित रखें और कभी साझा न करें। नीचे पुष्टि करने पर की-अपडेट लेनदेन पर हस्ताक्षर के लिए owner की का उपयोग होगा।",
            "this_will_strong_cancel_any_pending_recovery": "इससे वर्तमान पुनर्प्राप्ति खाते का वही मान पुनः प्रसारित करके <strong>कोई भी लंबित पुनर्प्राप्ति-खाता परिवर्तन रद्द</strong> हो जाएगा। 30-दिन का अनुरोध बदल दिया जाएगा; इस पूरे समय वर्तमान पुनर्प्राप्ति खाता लागू रहेगा।",
            "once_broadcast_the_chain_will_create_a": "प्रसारण के बाद चेन एक लंबित अनुरोध बनाएगी जो <strong>30 दिनों</strong> में प्रभावी होगा। तब तक आपका वर्तमान पुनर्प्राप्ति खाता (<0>@{{currentRecovery}}</0>) लागू रहेगा। आपसे आपकी <strong>owner की</strong> माँगी जाएगी।",
            "posting_description_1": "यह कुंजी सोशल नेटवर्किंग कार्यों के लिए है, जैसे पोस्ट करना, टिप्पणी करना और वोट देना। इस कुंजी की अनुमतियाँ सीमित हैं और इसका उपयोग मौद्रिक कार्यों के लिए नहीं किया जा सकता।",
            "posting_description_2": "Pixa-आधारित सोशल नेटवर्क (जैसे Pixagram.com) में लॉगिन के लिए इस कुंजी का उपयोग करें। इसे सुरक्षित रखें।",
            "active_description_1": "इस कुंजी के पास टोकन हस्तांतरित करने और विनिमय करने जैसे अधिक संवेदनशील मौद्रिक कार्यों के लिए अतिरिक्त अनुमतियाँ हैं।",
            "active_description_2": "वॉलेट से जुड़ा कार्य करते समय आपसे Active कुंजी से प्रमाणीकरण करने को कहा जा सकता है। Active Key केवल उन्हीं ऐप्स में डालें जिन पर आप भरोसा करते हैं, क्योंकि इस कुंजी तक पहुँच रखने वाला कोई भी व्यक्ति आपके टोकन ले सकता है।",
            "owner_description_1": "अन्य कुंजियाँ बदलने के लिए Owner कुंजी आवश्यक है। इस कुंजी के पास आपका अकाउंट पुनर्प्राप्त करने या अन्य कुंजियाँ बदलने की अतिरिक्त अनुमतियाँ हैं। यह सबसे महत्वपूर्ण कुंजी है और इसे ऑफ़लाइन सुरक्षित रखा जाना चाहिए।",
            "memo_description_1": "Memo कुंजी थोड़ी अलग है। Memo Key केवल ब्लॉकचेन के माध्यम से भेजे गए निजी संदेशों को एन्क्रिप्ट और डिक्रिप्ट कर सकती है।",
