            "the_price_feed_for_the_pixasupra_versus": "PixaSupra और Pixa का मूल्य फ़ीड लगभग 1:57 है। यह फ़ीड मुद्राओं के बीच प्रोत्साहन संतुलित करने के लिए उपयोग होता है। PixaSupra और Pixa ऐसा संतुलन चाहते हैं जहाँ ओरैकल-संदर्भित टोकन से <b>3.3 गुना अधिक</b> तरल टोकन हों, ताकि PixaSupra, Pixa पूंजीकरण के 30% से नीचे रहे। इसका अर्थ है कि आपूर्ति सुधार के लिए हमारे पास अब <b>3.7x</b> का मार्जिन है; यदि Pixa का मूल्य इतना गिरे, तो haircut नियम लागू होता है।",
