            "the_blockchain_can_emit_various_ratio_of": "ब्लॉकचेन PixaSupra और Pixa को विभिन्न अनुपातों में जारी कर सकती है। चूँकि PixaSupra ओरैकल-संदर्भित दर पर Pixa में रूपांतरित होता है, बकाया PixaSupra को Pixa पूंजीकरण के सापेक्ष तौला जाता है।",
