            "hide_no_problem_and_promise_no_more": "किसी समस्या को मत छिपाओ, और उससे अधिक वादा मत करो जितना निभाया जा सके।",
            "what_does_not_break_the_network_strengthens": "जो नेटवर्क को तोड़ नहीं पाता, वह उसे और मजबूत करता है।",
            "to_create_and_to_curate_is_worth": " रचना और क्यूरेशन, चुपचाप थामे रहने से अधिक मूल्यवान हैं; जो लोग सामने आते हैं, वही Pixa का जीवित पदार्थ हैं, और यह सबसे पहले उन्हीं के लिए बना है।",
            "and_most_beautiful_of_all_are_the": " — और सबसे सुंदर वे हाथ हैं जो उन्हें गढ़ते हैं। कृति में रचनाकार का सम्मान करो।",
            "and_only_then_refine_your_work_to": " और उसके बाद ही अपनी कृति को माँजो कि वह ऊपर उठे। शिल्प का आनंद पहले आता है; कृति की महत्वाकांक्षा उसके बाद।",
            "for_greatness_lies_in_the_highest_to": " क्योंकि महानता सबसे ऊँचाई में बसती है। बार-बार पोस्ट करना अच्छा है; अच्छा पोस्ट करना उससे बड़ा है।",
            "but_let_your_highest_goal_be_their": " पर तुम्हारा सर्वोच्च लक्ष्य उनका अर्थ हो — क्योंकि जो अर्थ धारण करता है, वही टिकता है।",
            "for_conquest_is_never_accomplished_no_milestone": " क्योंकि विजय कभी पूरी नहीं होती। कोई पड़ाव शिखर नहीं है; काम कभी समाप्त नहीं होता।",
            "lift_the_smallest_accounts_as_you_climb": " चढ़ते हुए सबसे छोटे खातों को भी ऊपर उठाओ, क्योंकि आज की छोटी मछली कल की उस्ताद है।",
            "but_treat_it_sometimes_as_an_impostor": " पर कभी-कभी उसे छलिया समझो — और सदा न्यायी रहो। भीड़ जिसे चाहती है, वह सदा सर्वोत्तम नहीं होता; अपने ही निर्णायक बने रहो।",
            "to_dislike_is_your_right_and_to": " नापसंद करना तुम्हारा अधिकार है, और परखना सेंसर करना नहीं है; जो कृति तुम्हें हिलाती नहीं, उसे डाउनवोट दो या आगे बढ़ जाओ।",
            "a_community_is_known_by_how_it": " समुदाय इसी से पहचाना जाता है कि वह कमजोरों को कैसे ढाँपता है; अपनी शक्ति को सृजन की ओर मोड़ो, कभी किसी और के विरुद्ध नहीं।",
            "let_every_tool_serve_the_creator_and": " हर औजार रचनाकार की सेवा करे, और कभी उसकी जगह न ले।",
            "in_your_work_and_in_your_dealings": " — अपने काम में भी और अपने व्यवहार में भी; क्योंकि ईमानदारी ही वह चट्टान है जिस पर हर शक्ति खड़ी होती है।",
            "contribute_to_it_not_for_today_or": " इसमें योगदान करो, न आज के लिए न कल के लिए, बल्कि हर काल के लिए।",
            "it_funds_development_and_the_protocol_the": " — यह विकास और प्रोटोकॉल को सहारा देता है। Pixa का प्रचार उसके लोगों का है, कभी उसके कोषागार का नहीं।",
            "the_foundation_stewards_it_does_not_rule": " Foundation संभालता है; शासन नहीं करता। यहाँ जो बनता है, वह उन सबका है जो उसे बनाते हैं।",
            "should_governance_ever_fail_the_community_may": " यदि शासन-व्यवस्था कभी विफल हो, तो समुदाय इस काम को समूचा कहीं और ले जा सकता है।",
            "what_is_true_is_said_plainly_even": " जो सच है वह सीधे कहा जाता है, तब भी जब एक सुविधाजनक कल्पना आसान होती हो।",
            "we_endure_by_bending_to_the_storm": " हम तूफान के आगे झुककर टिकते हैं, यह बहाना करके नहीं कि कोई तूफान आएगा ही नहीं।",
            "uniquely_we_are_free_together_we_are_stronger": "अनूठे होकर हम स्वतंत्र हैं; एकजुट होकर हम और सशक्त हैं।",
            "these_principles_are_the_foundation_of_pixa": "ये सिद्धांत Pixa की नींव हैं, और उस समुदाय की भी जिसे हम उस पर खड़ा करते हैं — ईमानदार, न्यायपूर्ण, स्थायी और एकजुट। प्रोटोकॉल केवल उतना ही वर्जित करता है जितना अनिवार्य है; उस रेखा से परे जो कुछ भी अच्छा है, वह वह चरित्र है जिसे हम चुनते हैं। यही वह चरित्र है: वह भावना जिससे हम रचते हैं, वह ढंग जिससे हम एक-दूसरे से पेश आते हैं, और वह कसौटी जिस पर हम स्वयं को परखते हैं। ये किसी को बलपूर्वक नहीं बाँधते, और फिर भी हम सबको बाँधते हैं।",
