            "the_interface_is_intended_for_users_aged": "इंटरफ़ेस 16 वर्ष या उससे अधिक आयु के उपयोगकर्ताओं के लिए, या आप पर लागू कानून द्वारा अपेक्षित किसी उच्चतर न्यूनतम आयु वाले उपयोगकर्ताओं के लिए अभिप्रेत है। यह 16 वर्ष से कम आयु के बच्चों के लिए लक्षित नहीं है, और हम जानबूझकर 16 वर्ष से कम आयु के बच्चों का व्यक्तिगत डेटा संसाधित नहीं करते; यदि आपको लगता है कि 16 वर्ष से कम आयु के किसी बच्चे ने हमें व्यक्तिगत डेटा प्रदान किया है, तो contact@pixarex.net पर हमसे संपर्क करें और हम उस पर कार्रवाई करेंगे। यदि आपकी आयु 18 वर्ष से कम है, तो कुछ सामग्री या डिजिटल-परिसंपत्ति सुविधाएँ अनुपलब्ध या प्रतिबंधित हो सकती हैं (शर्तें, खंड 2)। डेटा न्यूनीकरण हर जगह लागू होता है, और स्थायित्व की चेतावनी कम आयु के उपयोगकर्ताओं के लिए सबसे अधिक महत्वपूर्ण है: कभी भी व्यक्तिगत जानकारी प्रकाशित न करें - इसे कोई भी पूर्ववत नहीं कर सकता।",
