            "9_your_rights": "9. आपके अधिकार",
            "for_off_chain_data_you_have_the": "ऑफ़-चेन डेटा के लिए, आपको अपने निवास-स्थान के कानून के अंतर्गत उपलब्ध अधिकार प्राप्त हैं: पहुँच, सुधार, विलोपन, प्रतिबंध, आपत्ति, सुवाह्यता और सहमति वापस लेना। इनका प्रयोग करने के लिए contact@pixarex.net पर लिखें। आप अपने स्थानीय पर्यवेक्षी प्राधिकरण से शिकायत भी कर सकते हैं। इन अनुरोधों का उत्तर सदैव दिया जाता है: शर्तों का गैर-प्रत्युत्तर नियम सामग्री-मॉडरेशन संबंधी माँगों पर लागू होता है, डेटा-विषय के अधिकारों पर कभी नहीं।",
