            "in_short_courtesy_summary_not_binding_pixagram": "संक्षेप में (सुविधा हेतु दिया गया सारांश, बाध्यकारी नहीं): pixagram.com एक सार्वजनिक, अनुमति-रहित ब्लॉकचेन का सटीक दर्पण है। हम कभी भी आपकी कीज़ या आपकी निधियाँ अपने पास नहीं रखते। आप जो प्रकाशित करते हैं, वह सार्वजनिक और स्थायी है - आप और हम सहित कोई भी उसे मिटा नहीं सकता। क्या दिखाई देता है, यह सामान्यतः समुदाय के वोटों का अनुसरण करता है, जो इन शर्तों में वर्णित इंटरफ़ेस-स्तरीय उपायों के अधीन है। इंटरफ़ेस के माध्यम से खाता बनाने या उसका उपयोग करने के लिए आपकी आयु कम से कम 16 वर्ष होनी चाहिए, या आपको लागू कानून द्वारा अपेक्षित किसी उच्चतर न्यूनतम आयु की शर्त पूरी करनी होगी। इंटरफ़ेस कार्यस्थल पर देखने के लिए उपयुक्त वातावरण के रूप में संचालित किया जाता है और सामान्यतः पहचान या दस्तावेज़ी आयु सत्यापन की माँग नहीं करता।",
            "these_terms_of_use_the_terms_form": "ये उपयोग की शर्तें (“शर्तें”) आपके और Pixa Rex S.A. के बीच एक बाध्यकारी समझौता हैं, जो पनामा गणराज्य के कानूनों के अंतर्गत निगमित एक sociedad anónima है, Public Registry of Panama में Mercantile Folio No. 155788210 के अंतर्गत दर्ज है, और जिसका पता Advanced Tower Building, First Floor, Ricardo Arias Street, Panama City, Republic of Panama है (“ऑपरेटर”, “हम”, “हमें”)। ये शर्तें pixagram.com पर स्थित वेबसाइट और वेब इंटरफ़ेस तथा किसी भी संबद्ध सबडोमेन (“इंटरफ़ेस”) तक आपकी पहुँच और उनके उपयोग को नियंत्रित करती हैं। कानूनी पहचान संबंधी पत्राचार: contact@pixarex.net।",
