            "legal_agreement": "विधिक समझौता",
            "this_nft_license_agreement_the_agreement": "यह NFT लाइसेंस समझौता (“समझौता”) वे अनुकूलन-योग्य शर्तें निर्धारित करता है जिनके अंतर्गत रचनाकार (जिसे आगे “रचयिता” कहा गया है) डिजिटल कलाकृतियों के किसी विशिष्ट संग्रह (“संग्रह”) से संबद्ध अपूरणीय टोकनों (NFT) के क्रेता (“धारक”) को कुछ अधिकार प्रदान करता है। इस समझौते का उद्देश्य एक लचीला, पारदर्शी और निष्पक्ष लाइसेंसिंग ढाँचा प्रदान करना है, जो विभिन्न उपयोग-मामलों, व्यावसायिक मॉडलों और कलात्मक उद्देश्यों के अनुरूप ढल सके, और साथ ही यह सुनिश्चित करना है कि रचयिता के नैतिक अधिकार अक्षुण्ण और पूर्णतः संरक्षित रहें। यह संरचना विशेष रूप से उन NFT रचनाकारों के लिए बनाई गई है जो अपनी डिजिटल परिसंपत्तियों के धारकों को अनुकूलित उपयोग अधिकार प्रदान करना चाहते हैं, जिससे रचयिता द्वारा चुनी गई प्राथमिकताओं के अनुसार कलाकृति के साथ विविध अंतःक्रियाएँ और उसका विविध उपयोग संभव हो सके।",
            "ownership_and_moral_rights": "स्वामित्व और नैतिक अधिकार",
            "the_author_is_and_shall_remain_the_sole": "रचयिता अंतर्निहित कलाकृतियों और NFT से जुड़ी किसी भी संबद्ध सामग्री में समस्त बौद्धिक संपदा अधिकारों का एकमात्र और अनन्य स्वामी है और बना रहेगा। रचयिता समस्त नैतिक अधिकार अपने पास रखता है, जिनमें रचनाकार के रूप में पहचाने जाने का अधिकार तथा कृति के किसी भी ऐसे विरूपण, विकृतीकरण या अन्य संशोधन पर आपत्ति करने का अधिकार शामिल है जो उसके सम्मान या प्रतिष्ठा के लिए हानिकर हो। ये नैतिक अधिकार अहस्तांतरणीय और शाश्वत हैं, और सभी धारकों तथा तृतीय पक्षों द्वारा इनका सम्मान किया जाएगा। इस समझौते का अर्थ ऐसे अधिकारों के परित्याग या परिसीमन के रूप में नहीं लगाया जाएगा।",
            "license_options_for_the_holder": "धारक के लिए लाइसेंस विकल्प",
            "the_holder_of_an_nft_is_granted_a_non": "किसी NFT के धारक को उस NFT से संबद्ध डिजिटल कलाकृति का उपयोग करने के लिए एक गैर-अनन्य, विश्वव्यापी, रॉयल्टी-मुक्त लाइसेंस प्रदान किया जाता है, किंतु केवल उसी सीमा तक जिसकी नीचे रचयिता द्वारा स्पष्ट रूप से अनुमति दी गई है। यह लाइसेंस कड़ाई से स्वामित्व वाले विशिष्ट NFT से जुड़ा है और पुनर्विक्रय पर स्वतः हस्तांतरित हो जाता है। इस खंड का उद्देश्य रचयिता को प्रत्येक धारक को प्रदान किए जाने वाले अधिकारों का दायरा चुनने देना है, जिससे दोनों पक्षों को विधिक स्पष्टता और रचनात्मक लचीलापन मिलता है। सूचीबद्ध प्रत्येक अधिकार के लिए रचयिता यह इंगित कर सकता है कि धारक को उसका प्रयोग करने की अनुमति है या नहीं।",
